() => {
  // find scrollable containers
  const els = Array.from(document.querySelectorAll('*')).filter(e => {
    const cs = getComputedStyle(e);
    return /(auto|scroll)/.test(cs.overflowY) && e.scrollHeight > e.clientHeight + 10;
  });
  const info = els.slice(0,5).map(e => ({ cls: (e.className||'').toString().slice(0,40), sh: e.scrollHeight, ch: e.clientHeight, st: e.scrollTop }));
  // scroll the biggest one to top then down to test
  const target = els.sort((a,b)=> (b.scrollHeight-b.clientHeight)-(a.scrollHeight-a.clientHeight))[0];
  let result = null;
  if (target) {
    target.scrollTop = 0;
    const top = target.scrollTop;
    target.scrollTop = 300;
    const down = target.scrollTop;
    result = { top, down, works: down !== top };
  }
  return { containers: info, scrollTest: result };
}

